begin;
create extension if not exists pgcrypto;
create schema if not exists private;
create type public.app_role as enum ('customer','support','admin','super_admin');
create type public.provider_status as enum ('draft','testing','active','suspended','retired');
create type public.offer_kind as enum ('sms_activation','private_rental','business_line');
create type public.inventory_status as enum ('available','reserved','assigned','unavailable','retired');
create type public.order_status as enum ('pending_payment','paid','provisioning','active','waiting_message','completed','expired','cancelled','failed','refunded','review_required');
create type public.payment_status as enum ('pending','successful','failed','reversed','refunded');
create type public.ledger_direction as enum ('credit','debit');
create type public.message_status as enum ('received','filtered','quarantined','deleted');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,phone_e164 text,country_code char(2) not null default 'NG',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(phone_e164 is null or phone_e164 ~ '^\\+[1-9][0-9]{7,14}$'));
create table public.user_roles(user_id uuid not null references auth.users(id) on delete cascade,role public.app_role not null default 'customer',granted_at timestamptz not null default now(),granted_by uuid references auth.users(id),primary key(user_id,role));
create table public.wallets(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete restrict,currency char(3) not null default 'NGN' check(currency='NGN'),created_at timestamptz not null default now());
create table public.wallet_transactions(id uuid primary key default gen_random_uuid(),wallet_id uuid not null references public.wallets(id) on delete restrict,user_id uuid not null references auth.users(id) on delete restrict,direction public.ledger_direction not null,amount_kobo bigint not null check(amount_kobo>0),balance_after_kobo bigint,reference text not null unique,transaction_type text not null check(transaction_type in ('deposit','purchase','refund','adjustment','reversal')),description text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index wallet_transactions_owner_date_idx on public.wallet_transactions(user_id,created_at desc);
create table public.payment_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete restrict,wallet_id uuid not null references public.wallets(id) on delete restrict,gateway text not null check(gateway in ('paystack','flutterwave')),gateway_reference text not null,amount_kobo bigint not null check(amount_kobo>0),currency char(3) not null default 'NGN' check(currency='NGN'),status public.payment_status not null default 'pending',gateway_transaction_id text,verified_at timestamptz,raw_event jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(gateway,gateway_reference));
create table public.providers(id uuid primary key default gen_random_uuid(),code text not null unique,display_name text not null,status public.provider_status not null default 'draft',supports_sms boolean not null default false,supports_voice boolean not null default false,supports_rentals boolean not null default false,supports_webhooks boolean not null default false,documentation_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.provider_products(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.providers(id) on delete restrict,external_product_id text not null,country_iso2 char(2) not null,country_name text not null,service_code text not null,service_name text not null,channel text not null default 'sms',offer_kind public.offer_kind not null,number_class text,term_minutes integer check(term_minutes is null or term_minutes>0),currency char(3) not null,wholesale_amount_minor bigint check(wholesale_amount_minor is null or wholesale_amount_minor>=0),retail_amount_kobo bigint check(retail_amount_kobo is null or retail_amount_kobo>=0),inventory_count integer,verified_at timestamptz,active boolean not null default false,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider_id,external_product_id,country_iso2,service_code,offer_kind));
create index provider_products_catalog_idx on public.provider_products(active,country_iso2,channel,service_code);
create table public.numbers(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.providers(id) on delete restrict,provider_number_ref text not null,e164_ciphertext bytea,e164_last4 char(4),country_iso2 char(2) not null,service_code text,channel text,offer_kind public.offer_kind not null,number_class text,status public.inventory_status not null default 'available',capabilities jsonb not null default '{}'::jsonb,provider_metadata jsonb not null default '{}'::jsonb,last_verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider_id,provider_number_ref));
create index numbers_inventory_idx on public.numbers(country_iso2,channel,offer_kind,status);
create table public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete restrict,provider_product_id uuid references public.provider_products(id) on delete restrict,number_id uuid references public.numbers(id) on delete restrict,offer_kind public.offer_kind not null,status public.order_status not null default 'pending_payment',retail_amount_kobo bigint not null check(retail_amount_kobo>=0),currency char(3) not null default 'NGN' check(currency='NGN'),idempotency_key text not null,expires_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,idempotency_key));
create index orders_owner_date_idx on public.orders(user_id,created_at desc);
create table public.provider_orders(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete restrict,provider_id uuid not null references public.providers(id) on delete restrict,provider_order_ref text not null,status text not null,wholesale_amount_minor bigint,wholesale_currency char(3),request_id text,last_provider_response jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider_id,provider_order_ref));
create table public.messages(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete restrict,user_id uuid not null references auth.users(id) on delete restrict,provider_id uuid not null references public.providers(id) on delete restrict,provider_message_ref text,sender text,body_ciphertext bytea not null,received_at timestamptz not null,status public.message_status not null default 'received',retention_until timestamptz,created_at timestamptz not null default now(),unique(provider_id,provider_message_ref));
create index messages_owner_date_idx on public.messages(user_id,received_at desc);
create table public.pricing_rules(id uuid primary key default gen_random_uuid(),provider_product_id uuid references public.provider_products(id) on delete cascade,country_iso2 char(2),service_code text,channel text,offer_kind public.offer_kind,markup_type text not null check(markup_type in ('fixed','percentage')),markup_value numeric(12,4) not null check(markup_value>=0),minimum_retail_kobo bigint check(minimum_retail_kobo is null or minimum_retail_kobo>=0),active boolean not null default true,starts_at timestamptz not null default now(),ends_at timestamptz,created_at timestamptz not null default now(),check(ends_at is null or ends_at>starts_at));
create table public.refunds(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete restrict,user_id uuid not null references auth.users(id) on delete restrict,amount_kobo bigint not null check(amount_kobo>0),reason text not null,status text not null default 'pending' check(status in ('pending','approved','rejected','processed')),wallet_transaction_id uuid references public.wallet_transactions(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,body text not null,category text not null,read_at timestamptz,created_at timestamptz not null default now());
create index notifications_owner_date_idx on public.notifications(user_id,created_at desc);
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_user_id uuid references auth.users(id) on delete set null,action text not null,entity_type text not null,entity_id text,ip_hash text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['profiles','user_roles','wallets','wallet_transactions','payment_transactions','providers','provider_products','numbers','orders','provider_orders','messages','pricing_rules','refunds','notifications','audit_logs'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy profiles_select_own on public.profiles for select to authenticated using ((select auth.uid())=id);
create policy profiles_update_own on public.profiles for update to authenticated using ((select auth.uid())=id) with check ((select auth.uid())=id);
create policy roles_select_own on public.user_roles for select to authenticated using ((select auth.uid())=user_id);
create policy wallets_select_own on public.wallets for select to authenticated using ((select auth.uid())=user_id);
create policy ledger_select_own on public.wallet_transactions for select to authenticated using ((select auth.uid())=user_id);
create policy payments_select_own on public.payment_transactions for select to authenticated using ((select auth.uid())=user_id);
create policy orders_select_own on public.orders for select to authenticated using ((select auth.uid())=user_id);
create policy messages_select_own on public.messages for select to authenticated using ((select auth.uid())=user_id);
create policy refunds_select_own on public.refunds for select to authenticated using ((select auth.uid())=user_id);
create policy notifications_select_own on public.notifications for select to authenticated using ((select auth.uid())=user_id);
create policy notifications_update_own on public.notifications for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy provider_products_public_active on public.provider_products for select to anon,authenticated using(active=true);
create policy providers_public_active on public.providers for select to anon,authenticated using(status='active');
create or replace function private.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'name',new.raw_user_meta_data->>'full_name')); insert into public.wallets(user_id,currency) values(new.id,'NGN'); insert into public.user_roles(user_id,role) values(new.id,'customer'); return new; end; $$;
revoke all on function private.handle_new_user() from public,anon,authenticated;
create trigger on_auth_user_created after insert on auth.users for each row execute function private.handle_new_user();
commit;